package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.session.SessionStore;
import java.util.concurrent.CompletionStage;

/** Owner of Agent providers, tools, sessions, and their executors. */
public interface AgentRuntime extends AutoCloseable {
    AgentSession newSession(SessionOptions options);
    AgentSession loadSession(String sessionId);
    SessionStore sessionStore();
    CompletionStage<Void> closeAsync();

    @Override
    default void close() {
        closeAsync().toCompletableFuture().join();
    }
}

